    violations, applicable = [], 0
    for route in routes:
        pattern = {'classicFrontDoor': r'/routingRules/[^/?#]+', 'afd': r'/afdEndpoints/[^/?#]+/routes/[^/?#]+', 'classicCdn': r'/endpoints/[^/?#]+(?:/customDomains/[^/?#]+)?'}[family]
